import * as T from 'three';
import {OrbitControls} from './assets/vendor/OrbitControls.js';

const $=s=>document.querySelector(s), colors={steel:0x8e9a9a,dark:0x41555b,gold:0xc5a254,feed:0x38a9c5,high:0xe18437,back:0xa88ac9,body:0xbac4c0};
const systems={
 separados:{name:'Bomba e inyectores separados',short:'Bomba e inyectores separados',slide:'33 (figura 442); apoyo: N6, 3–4 y 16–19',description:'Una bomba en línea reúne un elemento de bombeo por cilindro. Cada salida impulsa combustible por su propio tubo hasta un inyector separado.',scope:'Se representan cuatro elementos para facilitar la lectura; la figura 442 muestra una bomba de seis. Se conservan depósito, alimentación, filtro, avance, regulación, inyectores y retorno. La carrera de los émbolos y la apertura de las agujas se muestran ampliadas.',phases:[['Llenado','El combustible filtrado llena el elemento de bombeo con el émbolo abajo.'],['Compresión','La leva levanta el émbolo. Cerrada la admisión, aumenta la presión del combustible.'],['Inyección','Abre la válvula de envío; la presión en el tubo levanta la aguja y sale el combustible pulverizado.'],['Corte y retorno','Cesa la impulsión; la aguja cierra por su resorte. Las fugas y el excedente vuelven al depósito.']]},
 distribuidor:{name:'Sistema de inyección con distribuidor',short:'Distribuidor independiente',slide:'31–32',description:'Las bombas de baja y alta presión alimentan un distribuidor independiente. Este comunica sucesivamente la alimentación con la salida del cilindro correspondiente.',scope:'Se sigue el esquema de la diapositiva 32: dos bombas con engranajes, regulador de caudal y distribuidor separado. No es la monobomba con distribuidor rotativo incorporado de la diapositiva 35. El accionamiento mecánico del inyector se representa simplificado con leva, varilla y balancín.',phases:[['Alimentación','La bomba de baja presión toma combustible del depósito y alimenta el circuito.'],['Elevación y dosificación','La etapa de alta presión alimenta el distribuidor. El regulador ajusta la cantidad según el mando.'],['Distribución e inyección','El rotor comunica una salida; el accionamiento del inyector acompaña la entrega al cilindro seleccionado.'],['Cambio de salida','Se corta la entrega a ese cilindro y el distribuidor continúa hacia la siguiente salida.']]},
 valvulas:{name:'Inyección por válvulas para el inyector',short:'Distribución por válvulas',slide:'29–30',description:'Una bomba eleva y regula la presión. Un bloque de válvulas de asiento, accionadas por levas, distribuye la entrega hacia los inyectores.',scope:'Se conservan bomba primaria, bomba de presión y regulación, bloque de distribución, engranajes y levas de la diapositiva 30. Las válvulas Poppet se muestran en corte didáctico. Depósito, filtrado y retorno se añaden como contexto auxiliar; su ubicación no procede de esa figura.',phases:[['Alimentación primaria','La bomba primaria abastece a la bomba de presión y regulación.'],['Compresión y regulación','La leva acciona la bomba; el combustible a presión llega al bloque de distribución.'],['Apertura de una válvula','La leva correspondiente desplaza la válvula de asiento y habilita la entrega al inyector.'],['Cierre','La válvula vuelve a su asiento; se interrumpe la entrega y continúa la secuencia del siguiente cilindro.']]}
};
let renderer,scene,camera,controls,root,parts=[],pipes=[],motions=[],labels=[],sprays=[],phase=0,running=false,explosion=0,selected='',system='',last=0,raf,cut=false;
const material=(c,extra={})=>new T.MeshStandardMaterial({color:c,roughness:.4,metalness:.45,...extra});
function mesh(g,geo,c,x=0,y=0,z=0,extra){const m=new T.Mesh(geo,material(c,extra));m.position.set(x,y,z);g.add(m);return m}
function cyl(g,r,h,x,y,z,c=colors.steel,axis='y',r2=r){const m=mesh(g,new T.CylinderGeometry(r2,r,h,32),c,x,y,z);if(axis==='x')m.rotation.z=Math.PI/2;if(axis==='z')m.rotation.x=Math.PI/2;return m}
function box(g,w,h,d,x,y,z,c=colors.body){const s=new T.Shape(),r=Math.min(w,h)*.15;s.moveTo(-w/2+r,-h/2);s.lineTo(w/2-r,-h/2);s.quadraticCurveTo(w/2,-h/2,w/2,-h/2+r);s.lineTo(w/2,h/2-r);s.quadraticCurveTo(w/2,h/2,w/2-r,h/2);s.lineTo(-w/2+r,h/2);s.quadraticCurveTo(-w/2,h/2,-w/2,h/2-r);s.lineTo(-w/2,-h/2+r);s.quadraticCurveTo(-w/2,-h/2,-w/2+r,-h/2);const m=mesh(g,new T.ExtrudeGeometry(s,{depth:d,bevelEnabled:true,bevelSize:.06,bevelThickness:.06,bevelSegments:2,steps:1,curveSegments:8}),c,x,y,z-d/2);return m}
function tube(g,pts,r,c){const path=new T.CatmullRomCurve3(pts.map(p=>new T.Vector3(...p)),false,'centripetal');return {mesh:mesh(g,new T.TubeGeometry(path,48,r,8,false),c),path}}
function spring(g,x,y,z,r=.16,h=.65){const pts=Array.from({length:161},(_,i)=>[x+r*Math.cos(i/160*Math.PI*14),y+h*i/160,z+r*Math.sin(i/160*Math.PI*14)]);tube(g,pts,.027,colors.dark)}
function lathe(g,x,y,z,profile,c){return mesh(g,new T.LatheGeometry(profile.map(p=>new T.Vector2(...p)),32),c,x,y,z)}
function gear(g,x,y,z,r=.4){const q=new T.Group();q.position.set(x,y,z);g.add(q);cyl(q,r,.14,0,0,0,colors.gold,'z');for(let i=0;i<16;i++){const a=i*Math.PI/8,m=mesh(q,new T.BoxGeometry(.12,.17,.18),colors.gold,Math.cos(a)*r,Math.sin(a)*r,0);m.rotation.z=a-Math.PI/2}cyl(q,.12,.22,0,0,0,colors.dark,'z');return q}
function part(id,name,position,explode,fn,connection,note,internal=false){const g=new T.Group();g.position.fromArray(position);g.userData={id,base:new T.Vector3(...position),explode:new T.Vector3(...explode)};root.add(g);const p={id,name,g,fn,connection,note,internal,number:parts.length+1};parts.push(p);return g}
function shell(m){m.userData.shell=true;return m}
function pipe(id,name,pts,type,description,index=-1){const g=part(id,name,[0,0,0],[0,0,0],description,'Conecta las bocas de entrada y salida indicadas por su recorrido.','En despiece se oculta: las conexiones sólo son válidas con el conjunto armado.');g.userData.pipe=true;const t=tube(g,pts,.055,colors[type]);const dot=mesh(g,new T.SphereGeometry(.095,12,8),colors[type],0,0,0,{emissive:colors[type],emissiveIntensity:.5});pipes.push({...t,dot,g,type,index});g.userData.anchor=new T.Vector3(...pts[Math.floor(pts.length/2)]);return g}
function common(){
 const tank=part('tank','Depósito de combustible',[-4.8,.7,1.1],[-1,-.2,1],'Almacena el combustible que abastece al sistema.','Su salida llega a la bomba de alimentación; el retorno vuelve al depósito.','Elemento 6 de la figura 442; auxiliar de contexto en los otros dos sistemas.');
 shell(cyl(tank,.67,1.8,0,0,0,colors.body,'x'));for(const x of [-.65,.65]){cyl(tank,.7,.1,x,0,0,colors.dark,'x');box(tank,.2,.35,.7,x,-.65,0,colors.dark)}cyl(tank,.18,.17,0,.73,0,colors.gold);box(tank,1.35,.35,.05,0,-.1,.68,colors.feed);
 const filter=part('filter','Filtro principal',[-4.1,2.6,.6],[-1,1,.3],'Retiene impurezas antes de los elementos de precisión.','Bomba de alimentación → filtro → etapa de alta presión.','Elemento 8 de la figura 442.');shell(cyl(filter,.32,.9,0,0,0,colors.body));cyl(filter,.4,.13,0,.5,0,colors.dark);cyl(filter,.1,.16,0,-.54,0,colors.gold);for(let i=0;i<10;i++){const a=i*Math.PI/5;cyl(filter,.04,.76,.23*Math.cos(a),0,.23*Math.sin(a),colors.gold)}
 const feed=part('feed','Bomba de alimentación',[-4.8,1.15,-.8],[-1,-.5,-.8],'Entrega combustible a baja presión a la etapa siguiente.','Depósito → bomba de alimentación → filtro.','Bomba primaria en el sistema por válvulas; bomba de baja presión en el distribuidor.');pumpGears(feed,.65);
 pipe('suction','Aspiración del depósito',[[-4.8,.7,.6],[-5.1,.7,0],[-4.8,1.15,-.8]],'feed','Conduce combustible desde el depósito a la bomba primaria.');pipe('filter-line','Alimentación al filtro',[[-4.5,1.15,-.8],[-4.1,1.15,-.4],[-4.1,2.6,.6]],'feed','Lleva el combustible impulsado al filtro principal.');
}
function pumpGears(g,scale=1){const b=box(g,1.25*scale,.85*scale,.65,0,0,0,colors.body);shell(b);for(const x of [-.29,.29]){const q=gear(g,x*scale,0,.34,.29*scale);motions.push({kind:'gear',obj:q,sign:x<0?1:-1})}cyl(g,.12,.45,-.8*scale,0,0,colors.dark,'x');}
function injectors(mechanical=false){
 const body=part('injectors','Portainyectores',[0,0,0],[0,1,-.3],'Sostienen los componentes del inyector y reciben el combustible.','Cada tubo de alta presión termina en un inyector.','Geometría escalonada simplificada. Se representan cuatro cilindros.');
 const needles=part('needles',mechanical?'Vástagos de apertura':'Agujas de los inyectores',[0,0,0],[0,2,-.3],mechanical?'Transmiten el mando mecánico hacia el cierre del inyector.':'Cierran sobre su asiento; la presión de combustible vence al resorte para levantarlas.','Abren o cierran el paso a las toberas.','Desplazamiento ampliado para observarlo.',true);
 const springs=part('springs','Resortes de cierre',[0,0,0],[0,2.7,-.3],'Devuelven el cierre a su asiento al finalizar la inyección.','Actúan sobre el vástago o la aguja del inyector.','Resortes esquemáticos, sin valor de tarado.',true);
 const nozzles=part('nozzles','Toberas',[0,0,0],[0,-.4,-.7],'Pulverizan el combustible que entra en la cámara de combustión.','Reciben combustible al abrir el cierre del inyector.','El cono representa pulverización, no llama ni combustión.');
 for(let i=0;i<4;i++){const x=-1.5+i*1.5,z=-1.5;
 shell(lathe(body,x,3.7,z,[[.13,0],[.19,.18],[.19,.48],[.32,.5],[.32,1.12],[.25,1.2],[.25,1.45]],colors.steel));cyl(body,.38,.15,x,4.2,z,colors.gold);cyl(body,.19,.2,x,5.18,z,colors.dark);cyl(body,.1,.4,x-.31,4.6,z,colors.gold,'x');
 const needle=new T.Group();needle.position.set(x,3.73,z);needles.add(needle);cyl(needle,.06,1.15,0,.5,0,colors.gold);cyl(needle,.08,.17,0,-.12,0,colors.gold,'y',0);motions.push({kind:'needle',obj:needle,base:needle.position.clone(),i});spring(springs,x,4.55,z,.14,.52);
 lathe(nozzles,x,3.45,z,[[.06,0],[.12,.08],[.16,.3],[.19,.35]],colors.dark);
 const spray=mesh(root,new T.ConeGeometry(.28,.65,24,1,true),colors.high,x,3.12,z,{transparent:true,opacity:.45,side:T.DoubleSide,metalness:0});sprays.push({obj:spray,i});
 if(mechanical){const q=new T.Group();q.position.set(x,5.27,z);body.add(q);box(q,.7,.1,.14,.2,0,0,colors.gold);cyl(q,.1,.3,.35,0,0,colors.dark,'z');motions.push({kind:'rocker',obj:q,i});cyl(body,.045,1.5,x+.6,4.5,z,colors.gold);const cam=cyl(body,.17,.12,x+.6,3.65,z,colors.gold,'z');motions.push({kind:'gear',obj:cam,sign:1})}
 }
 for(const p of [body,needles,springs,nozzles])p.userData.anchor=new T.Vector3(1, p===springs?5.1:p===nozzles?3.5:4.7,-1.5);
 const ret=pipe('return','Retorno de fugas y excedente',[[-1.5,5.4,-1.5],[3.65,5.4,-1.5],[3.9,1,1.5],[-4,.9,1.5]],'back','Devuelve excedente y fugas de lubricación al depósito. El trazado auxiliar se simplifica.');for(let i=0;i<4;i++){const x=-1.5+i*1.5;tube(ret,[[x,4.9,-1.5],[x,5.15,-1.5],[x,5.4,-1.5]],.04,colors.back)}
}
function separated(){
 const housing=part('pump','Cuerpo de bomba en línea',[.7,1.5,.6],[0,-.5,.7],'Aloja un elemento de bombeo por cada cilindro.','Combustible filtrado → elementos → válvulas de envío → tubos individuales.','Elemento 1 de la figura 442; cuatro elementos visibles en lugar de seis.');shell(box(housing,5.3,1.05,1.05,0,0,0));for(const x of [-2,-1,0,1,2])cyl(housing,.06,.08,x,.32,.58,colors.dark,'z');
 const plungers=part('plungers','Émbolos de bombeo',[0,0,0],[0,1,.7],'Comprimen el combustible al subir impulsados por las levas.','Deslizan en sus camisas dentro de la bomba en línea.','La carrera está ampliada; no se reproduce la geometría de la hélice de dosificación.',true);
 const valves=part('delivery','Válvulas de envío',[0,0,0],[0,1.8,.7],'Abren durante la impulsión y cierran al cesar la entrega.','Entre cada elemento de bombeo y su tubo de alta presión.','N6, diapositivas 16–18: cierre y descarga para evitar inyecciones secundarias.',true);
 const shaft=part('cam','Árbol de levas',[.7,.7,.6],[0,-1,.7],'Convierte el giro en carreras sucesivas de los émbolos.','Recibe el movimiento del motor a través del variador de avance.','Secuencia visual 1–2–3–4, no orden de encendido de un motor particular.');cyl(shaft,.12,5.8,0,0,0,colors.dark,'x');
 for(let i=0;i<4;i++){const x=-1.5+i*1.5;const q=new T.Group();q.position.set(x,1.5,.6);plungers.add(q);cyl(q,.13,.8,0,.1,0,colors.gold);spring(q,0,-.45,0,.2,.5);motions.push({kind:'plunger',obj:q,base:q.position.clone(),i});shell(cyl(housing,.27,.65,x-.7,.6,0));cyl(valves,.17,.3,x,2.35,.6,colors.gold);spring(valves,x,2.5,.6,.1,.25);const cam=cyl(shaft,.3,.2,x-.7,.12,0,colors.gold,'x');motions.push({kind:'cam',obj:cam,i});pipe('high'+i,'Tubo de alta presión '+(i+1),[[x,2.7,.6],[x,3.2,.6],[x-.4,3.5,-.7],[x-.4,4.6,-1.5],[x,4.6,-1.5]],'high','Une el elemento '+(i+1)+' con su inyector; en una instalación real se respetan longitud y sección especificadas.',i)}
 plungers.userData.anchor=new T.Vector3(0,1.9,.6);valves.userData.anchor=new T.Vector3(.4,2.6,.6);
 const advance=part('advance','Variador de avance',[-2.5,.7,.6],[-.8,-.5,.7],'Modifica la relación angular del mando de la bomba según el diseño.','Entre accionamiento y árbol de levas.','Elemento 2 de la figura 442. No se simula una curva de avance.');cyl(advance,.45,.35,0,0,0,colors.dark,'x');cyl(advance,.28,.39,0,0,0,colors.gold,'x');
 const reg=part('regulator','Regulador centrífugo',[3.65,1.2,.6],[1,-.4,.7],'Adapta el dosado al régimen y al mando del motor.','Mueve el vástago de regulación de la bomba.','Elemento 4 de la figura 442; mecanismo interno simplificado.');shell(cyl(reg,.5,.65,0,0,0,colors.body,'x'));const g=gear(reg,0,0,.4,.25);motions.push({kind:'gear',obj:g,sign:1});
 const rack=part('rack','Vástago / cremallera',[.5,1.9,1.3],[0,.4,1.5],'Transmite la regulación a los elementos de bombeo para variar la cantidad entregada.','Regulador → cremallera → giro de los émbolos.','Elemento 3 de la figura 442.');cyl(rack,.065,5.8,0,0,0,colors.gold,'x');for(let i=0;i<24;i++)box(rack,.07,.1,.1,-2.5+i*.2,0,0,colors.gold);
 pipe('feed-high','Entrada a bomba en línea',[[-4.1,2.6,.6],[-3.3,2.6,.6],[-3.1,1.8,.6],[-1.5,1.8,.6]],'feed','Combustible filtrado hacia la galería de alimentación.');
}
function distributor(){
 const high=part('highpump','Bomba de alta presión',[2.6,1,.7],[1,-.4,.8],'Eleva la presión del combustible que alimenta el distribuidor.','Recibe de la etapa de baja presión y entrega al distribuidor.','Se conserva la representación de engranajes del esquema 32.');pumpGears(high);
 const housing=part('distributor','Cuerpo del distribuidor',[.1,2.7,0],[0,.7,.5],'Aloja el elemento que comunica sucesivamente con las salidas.','Entrada común desde la bomba; una salida por cada inyector.','Distribuidor independiente de la bomba, según la diapositiva 32.');shell(cyl(housing,.75,.55,0,0,0,colors.body,'z'));for(let i=0;i<8;i++){const a=i*Math.PI/4;cyl(housing,.055,.08,.6*Math.cos(a),.6*Math.sin(a),.32,colors.dark,'z')}
 const rotor=part('rotor','Rotor distribuidor',[.1,2.7,.35],[0,.7,1.5],'Al girar conecta la entrada con una salida cada vez.','El conducto radial selecciona la línea del cilindro.','Canal interno ilustrativo, ampliado y visible para estudiar.',true);cyl(rotor,.48,.12,0,0,0,colors.gold,'z');box(rotor,.55,.1,.08,.22,0,.1,colors.high);cyl(rotor,.12,.16,0,0,.1,colors.dark,'z');motions.push({kind:'rotor',obj:rotor});
 const reg=part('meter','Regulador de caudal',[1.1,1.8,.7],[1,.2,1.1],'Ajusta la cantidad de combustible del circuito.','Actúa sobre el suministro de combustible al distribuidor.','No se representa como un inyector-bomba ni como una bomba rotativa integrada.');cyl(reg,.19,.65,0,0,0,colors.gold);cyl(reg,.09,.3,0,-.45,0,colors.steel);box(reg,.6,.1,.14,.15,-.55,0,colors.dark);
 pipe('feed-high','Alimentación de alta presión',[[-4.1,2.6,.6],[-3,2.6,1.4],[-3,.7,1.4],[2.6,.7,1.4],[2.6,1,.7]],'feed','Combustible filtrado hacia la bomba de alta presión.');pipe('high-common','Impulsión al distribuidor',[[2.6,1.4,.7],[2.6,2,.7],[1.1,2,.7],[.1,2.1,0]],'high','Suministro presurizado al distribuidor.');
 for(let i=0;i<4;i++){const a=i*Math.PI/2,x=-1.5+i*1.5,pt=[.1+Math.cos(a)*.72,2.7+Math.sin(a)*.72,0];pipe('high'+i,'Salida del distribuidor '+(i+1),[pt,[pt[0],3.7+i*.13,0],[x-.4,3.9+i*.13,-1],[x-.4,4.6,-1.5],[x,4.6,-1.5]],'high','Salida individual habilitada por el rotor hacia el inyector '+(i+1)+'.',i)}
}
function poppets(){
 const pump=part('pressure','Bomba de presión y regulación',[3,1.9,.6],[1.1,.4,.6],'Eleva la presión y regula la entrega del combustible.','Bomba primaria → bomba de presión → bloque de distribución.','Disposición de la diapositiva 30, con leva de accionamiento.');shell(cyl(pump,.45,1.1,0,0,0,colors.gold));cyl(pump,.54,.15,0,-.5,0,colors.dark);const pl=cyl(pump,.12,.7,0,-.75,0);motions.push({kind:'plunger',obj:pl,base:pl.position.clone(),i:0});spring(pump,0,-.65,0,.25,.4);
 const block=part('block','Bloque de distribución',[.4,2.3,.3],[0,.5,.6],'Contiene las válvulas que habilitan las salidas a los inyectores.','Recibe combustible de la bomba de presión y regulación.','La carcasa se transparenta para mostrar los asientos.');shell(box(block,4.7,.8,.85,0,0,0,colors.dark));
 const valves=part('poppets','Válvulas Poppet',[0,0,0],[0,1.6,.8],'Las levas desplazan cada válvula de asiento para distribuir la entrega.','Cada válvula comunica el bloque con un inyector.','Son válvulas de distribución; no son los émbolos de una bomba en línea.',true);
 const shaft=part('cam','Árbol de levas de distribución',[.5,1,.3],[0,-.5,1],'Acciona las válvulas en la secuencia prevista.','Engranajes de mando → levas → vástagos de válvula.','Giro y desplazamientos ralentizados.');cyl(shaft,.1,5,0,0,0,colors.dark,'x');
 const drive=part('drive','Engranajes de mando',[-2.5,.75,.3],[-.6,-.5,.7],'Sincronizan el eje de accionamiento con el árbol de distribución.','Transmisión mecánica entre los dos ejes.','Representación simplificada del mando de la figura.');for(const y of [0,.75]){const g=gear(drive,0,y,0,.36);motions.push({kind:'gear',obj:g,sign:y?1:-1})}cyl(drive,.09,5.8,2.5,0,0,colors.dark,'x');
 for(let i=0;i<4;i++){const x=-1.5+i*1.5;const q=new T.Group();q.position.set(x,1.6,.3);valves.add(q);cyl(q,.055,1.1,0,0,0,colors.gold);cyl(q,.19,.1,0,.5,0,colors.gold);spring(q,0,.07,0,.12,.35);motions.push({kind:'poppet',obj:q,base:q.position.clone(),i});const c=cyl(shaft,.26,.15,x-.5,.08,0,colors.gold,'x');motions.push({kind:'cam',obj:c,i});pipe('high'+i,'Salida de válvula '+(i+1),[[x,2.7,.3],[x,3.1,.3],[x-.4,3.5,-.8],[x-.4,4.6,-1.5],[x,4.6,-1.5]],'high','Salida del bloque hacia el inyector '+(i+1)+'; se habilita con su válvula.',i)}valves.userData.anchor=new T.Vector3(0,2.2,.3);
 const pc=cyl(pump,.3,.18,0,-1.1,0,colors.gold,'x');motions.push({kind:'cam',obj:pc,i:0});
 pipe('feed-high','Entrada a bomba de presión',[[-4.1,2.6,.6],[-3,2.9,1.3],[3,2.9,1.3],[3,2.1,.6]],'feed','Combustible filtrado hacia la bomba de presión.');pipe('high-common','Impulsión al bloque',[[3,2.4,.6],[3,2.9,.3],[2.4,2.9,.3],[2.4,2.3,.3]],'high','Entrega de la bomba al bloque distribuidor.');
}
function disposeRoot(){if(!root)return;const geometries=new Set(),materials=new Set();root.traverse(o=>{if(o.geometry)geometries.add(o.geometry);if(o.material)materials.add(o.material)});geometries.forEach(g=>g.dispose());materials.forEach(m=>m.dispose());scene.remove(root)}
function choose(id){selected=id;const p=parts.find(p=>p.id===id);if(!p)return;$('#detail').innerHTML=`<div class="number">COMPONENTE ${String(p.number).padStart(2,'0')}</div><h3>${p.name}</h3><h4>Función</h4><p>${p.fn}</p><h4>Conexiones</h4><p>${p.connection}</p><h4>Para interpretar el modelo</h4><p>${p.note}</p>`;document.querySelectorAll('[data-part]').forEach(b=>b.classList.toggle('active',b.dataset.part===id));labels.forEach(l=>l.el.classList.toggle('selected',l.p.id===id));applyView();}
function build(id){if(!systems[id])id='separados';disposeRoot();system=id;phase=0;running=false;explosion=0;parts=[];pipes=[];motions=[];sprays=[];root=new T.Group();scene.add(root);$('#explode').value=0;$('#explode-value').value='0%';$('#isolate').checked=false;$('#play').textContent='▶ Animar';const s=systems[id];$('#system-title').textContent=s.name;$('#system-description').textContent=s.description;$('#source-image').src=`assets/inyeccion/${id}.png`;$('#source-text').textContent='Fuente: N9 · Circuitos de combustible y cámara de combustión · CSMN Gastón Tolay. Diapositiva '+s.slide+'.';$('#scope').textContent=s.scope;common();injectors(id==='distribuidor');({separados:separated,distribuidor:distributor,valvulas:poppets})[id]();
 $('#parts').innerHTML=parts.map(p=>`<button data-part="${p.id}" title="${p.name}">${p.number}. ${p.name}</button>`).join('');$('#parts').querySelectorAll('button').forEach(b=>b.onclick=()=>choose(b.dataset.part));$('#count').textContent=parts.length+' piezas';$('#labels').innerHTML='';$('#leaders').innerHTML='';labels=parts.filter(p=>!p.g.userData.pipe).map(p=>{const el=document.createElement('button');el.className='label';el.innerHTML=`<b>${p.number}</b>${p.name}`;el.onclick=()=>choose(p.id);$('#labels').append(el);const line=document.createElementNS('http://www.w3.org/2000/svg','path');line.setAttribute('fill','none');line.setAttribute('stroke','#a18b72');line.setAttribute('stroke-width','1');$('#leaders').append(line);return {p,el,line}});$('#systems').querySelectorAll('button').forEach(b=>{b.classList.toggle('active',b.dataset.system===id);b.setAttribute('aria-pressed',String(b.dataset.system===id))});choose(id==='separados'?'pump':id==='distribuidor'?'distributor':'block');resetView();history.replaceState(null,'','#'+id);updateMotion();}
function resetView(){camera.position.set(10,8,13);controls.target.set(-.5,2.6,0);controls.update();}
function applyView(){const isolate=$('#isolate').checked;for(const p of parts){p.g.position.copy(p.g.userData.base).addScaledVector(p.g.userData.explode,explosion);p.g.visible=(!isolate||p.id===selected)&&(!p.g.userData.pipe||explosion===0);p.g.traverse(o=>{if(o.material){const shellCut=o.userData.shell&&cut;o.material.transparent=!!shellCut;o.material.opacity=shellCut?.23:1;o.material.depthWrite=!shellCut;o.material.emissive.setHex(p.id===selected?0x3c210b:0);o.material.emissiveIntensity=.3}})}$('#play').disabled=explosion>0||isolate;$('#step').disabled=explosion>0||isolate;$('#view-caption').textContent=isolate?'PIEZA AISLADA':explosion>0?'DESPIECE · CONEXIONES RETIRADAS':'CONJUNTO ARMADO';$('#mode-note').textContent=explosion>0||isolate?'Animación pausada. Las tuberías se ocultan en despiece para no representar conexiones falsas.':'Animación didáctica ralentizada. Los colores indican el recorrido, no valores de presión.';}
function updateMotion(){const cycle=phase%4,idx=Math.floor(phase/4)%4,stage=Math.floor(cycle),lift=stage===1?(cycle-1):stage===2?1:stage===3?1-(cycle-3):0;const delivering=stage===2&&explosion===0&&!$('#isolate').checked;
 for(const m of motions){const active=m.i===idx;if(m.kind==='gear')m.obj.rotation.z=phase*.7*m.sign;if(m.kind==='rotor')m.obj.rotation.z=(idx+(stage===3?cycle-3:0))*Math.PI/2;if(m.kind==='cam')m.obj.rotation.x=phase*Math.PI/2+m.i*Math.PI/2;if(['plunger','needle','poppet'].includes(m.kind)){m.obj.position.copy(m.base);m.obj.position.y+=(m.kind==='plunger'?(active?lift*.24:0):(active&&stage===2?.12:0))}if(m.kind==='rocker')m.obj.rotation.z=active&&stage===2?-.16:0;}
 for(const p of pipes){p.dot.visible=explosion===0&&!$('#isolate').checked&&(p.type!=='high'||(p.index<0?stage>0:delivering&&p.index===idx));p.dot.position.copy(p.path.getPointAt((phase*.65)%1));p.mesh.material.emissive.setHex(p.type==='high'&&delivering&&p.index===idx?colors.high:0);p.mesh.material.emissiveIntensity=.5}
 sprays.forEach(s=>s.obj.visible=delivering&&s.i===idx);const ph=systems[system].phases[stage];$('#phase-number').textContent=String(stage+1).padStart(2,'0');$('#phase-title').textContent=ph[0]+' · cilindro '+(idx+1);$('#phase-description').textContent=ph[1];
}
function drawLabels(){const w=$('#scene').clientWidth,h=$('#scene').clientHeight,used=[];for(const l of [...labels].sort((a,b)=>Number(b.p.id===selected)-Number(a.p.id===selected))){const {p,el,line}=l;line.style.display='none';const enabled=$('#names').checked&&p.g.visible&&(!p.internal||p.id===selected||explosion>.1);if(!enabled){el.hidden=true;continue}const v=(p.g.userData.anchor||new T.Vector3(0,.55,0)).clone();p.g.localToWorld(v);v.project(camera);let x=(v.x*.5+.5)*w,y=(-v.y*.5+.5)*h;const bw=Math.min(el.offsetWidth||130,190),bh=25;const anchorX=x,anchorY=y;let rect={x:x-bw/2,y:y-bh,w:bw,h:bh};for(let n=0;n<7&&used.some(r=>rect.x<r.x+r.w+3&&rect.x+rect.w>r.x-3&&rect.y<r.y+r.h+3&&rect.y+rect.h>r.y-3);n++){y-=29;rect.y=y-bh}el.hidden=v.z>1||v.z< -1||x<25||x>w-25||y<25||y>h;if(el.hidden)continue;el.style.left=Math.max(bw/2,Math.min(w-bw/2,x))+'px';el.style.top=y+'px';line.style.display='';const endX=Math.max(bw/2,Math.min(w-bw/2,x));line.setAttribute('d','M '+anchorX+' '+anchorY+' L '+endX+' '+y);used.push(rect)}}
function frame(t){raf=requestAnimationFrame(frame);const dt=Math.min((t-last)/1000,.05);last=t;if(running&&!document.hidden)phase=(phase+dt*Number($('#speed').value))%16;updateMotion();controls.update();scene.updateMatrixWorld();drawLabels();renderer.render(scene,camera)}
function init(){scene=new T.Scene();scene.background=new T.Color(0xeae8e2);camera=new T.PerspectiveCamera(38,1,.1,100);renderer=new T.WebGLRenderer({canvas:$('#canvas'),antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.outputColorSpace=T.SRGBColorSpace;scene.add(new T.HemisphereLight(0xffffff,0x9a8d75,2.5));const light=new T.DirectionalLight(0xfff4de,3);light.position.set(-3,10,8);scene.add(light);const fill=new T.DirectionalLight(0xe0efff,1.5);fill.position.set(5,6,-5);scene.add(fill);const grid=new T.GridHelper(18,36,0xc5c2b7,0xd7d5cc);grid.position.y=-.55;scene.add(grid);controls=new OrbitControls(camera,$('#canvas'));controls.enableDamping=true;controls.minDistance=7;controls.maxDistance=32;controls.maxPolarAngle=Math.PI*.85;controls.enablePan=true;new ResizeObserver(()=>{const w=$('#scene').clientWidth,h=$('#scene').clientHeight;camera.aspect=w/h;camera.updateProjectionMatrix();renderer.setSize(w,h,false)}).observe($('#scene'));
 $('#systems').innerHTML=Object.entries(systems).map(([id,s],i)=>`<button data-system="${id}"><small>0${i+1} / SISTEMA</small>${s.short}</button>`).join('');$('#systems').querySelectorAll('button').forEach(b=>b.onclick=()=>build(b.dataset.system));$('#play').onclick=()=>{running=!running;$('#play').textContent=running?'Ⅱ Pausar':'▶ Animar'};$('#step').onclick=()=>{running=false;$('#play').textContent='▶ Animar';phase=(Math.floor(phase)+1)%16};$('#reset').onclick=resetView;$('#explode').oninput=e=>{explosion=Number(e.target.value)/100;$('#explode-value').value=e.target.value+'%';running=false;$('#play').textContent='▶ Animar';applyView()};$('#cut').onchange=e=>{cut=e.target.checked;applyView()};$('#isolate').onchange=()=>{running=false;$('#play').textContent='▶ Animar';applyView()};let down;$('#canvas').addEventListener('pointerdown',e=>down=[e.clientX,e.clientY]);$('#canvas').addEventListener('pointerup',e=>{if(!down||Math.hypot(e.clientX-down[0],e.clientY-down[1])>5)return;const r=$('#canvas').getBoundingClientRect(),ray=new T.Raycaster();ray.setFromCamera(new T.Vector2((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1),camera);const hit=ray.intersectObjects(parts.filter(p=>p.g.visible).map(p=>p.g),true)[0];if(hit){let o=hit.object;while(o&&!o.userData.id)o=o.parent;if(o)choose(o.userData.id)}});window.addEventListener('hashchange',()=>{if(systems[location.hash.slice(1)]&&location.hash.slice(1)!==system)build(location.hash.slice(1))});build(location.hash.slice(1));requestAnimationFrame(frame);
 // Read-only QA snapshot: no rendering or application control exposed.
 window.injectionSnapshot=()=>({system,phase,running,explosion,selected,parts:parts.map(p=>({id:p.id,visible:p.g.visible,position:p.g.position.toArray()})),sprays:sprays.filter(s=>s.obj.visible).map(s=>s.i),geometries:renderer.info.memory.geometries});
}
try{init()}catch(e){$('#load-error').hidden=false;$('#load-error').textContent='No se pudo iniciar el visor 3D. Probá habilitar WebGL o abrir la página en otro navegador. Podés consultar la diapositiva original debajo.';console.error(e)}
